export default class extends Tac {
  // Overridden by the `flow` attribute on the tag.
  flow = 'password-login'
  languages = LANGUAGES
  active = LANGUAGES[0]

  get snippet() {
    const set = FLOWS[this.flow]
    return set ? set[this.active] || '' : ''
  }

  select(language) {
    this.active = language
  }
}
